<?php require dirname(__DIR__).'/core/bootstrap.php';$u=auth();$error='';if(is_post()){verify_csrf();try{$name=input('name',120);$email=strtolower(input('email',190));$old=input('current',200);$new=input('password',200);$row=one('SELECT password_hash FROM users WHERE id=?',[$u['id']]);if(!rate_limit('account',10,900)||!password_verify($old,$row['password_hash']))throw new InvalidArgumentException('Senha atual inválida ou muitas tentativas.');if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL))throw new InvalidArgumentException('Nome ou e-mail inválido.');$exists=one('SELECT id FROM users WHERE email=? AND id<>?',[$email,$u['id']]);if($exists)throw new InvalidArgumentException('E-mail indisponível.');if($new!==''&&strlen($new)<12)throw new InvalidArgumentException('A nova senha precisa de 12 caracteres.');run('UPDATE users SET name=?,email=?,password_hash=? WHERE id=?',[$name,$email,$new!==''?password_hash($new,PASSWORD_DEFAULT):$row['password_hash'],$u['id']]);session_regenerate_id(true);audit('conta_atualizada');flash('Dados atualizados.');go('cliente/conta.php');}catch(InvalidArgumentException $ex){$error=$ex->getMessage();}}$admin=false;require ROOT.'/includes/panel.php';?><h1>Minha conta.</h1><?php if($error):?><div class="errors"><?=e($error)?></div><?php endif;?><form method="post"><?php csrf();?><label class="field">Nome<input name="name" required value="<?=e($u['name'])?>" maxlength="120"></label><label class="field">E-mail<input name="email" type="email" required value="<?=e($u['email'])?>" maxlength="190"></label><label class="field">Senha atual para confirmar<input name="current" type="password" required maxlength="200" autocomplete="current-password"></label><label class="field">Nova senha (opcional)<input name="password" type="password" minlength="12" maxlength="200" autocomplete="new-password"></label><button class="primary">Salvar alterações</button></form><?php require ROOT.'/includes/endpanel.php';?>
